    'dlp.macT': 'Install on Mac',
    'dlp.mac1': 'Pick a file: <code>…-mac-arm64.dmg</code> for Apple chips (M1 and later), <code>…-mac-x64.dmg</code> for Intel',
    'dlp.mac2': 'Open the dmg and drag <strong>{app}</strong> into Applications',
    'dlp.mac3': 'Open it from Applications. If it says Apple “could not verify” it is free of malware, click <strong>Done</strong> (don’t move it to the Trash)',
    'dlp.mac4': 'System Settings → <strong>Privacy &amp; Security</strong> → <strong>Open Anyway</strong> under “Security”, then your password',
    'dlp.mac5': 'Click <strong>Open Anyway</strong> again. Your fairy appears',
    'dlp.macX': 'Still won’t open, or it says the app “is damaged”? Don’t move it to the Trash. Run this in Terminal, then open it again.',
    'dlp.xattr': 'xattr -dr com.apple.quarantine /Applications/{app}.app',
    'dlp.macShot': 'The first time you use Look together, turn on {app} in System Settings → Privacy &amp; Security → <strong>Screen &amp; System Audio Recording</strong> and restart the app.',
    'dlp.winT': 'Install on Windows',
    'dlp.win1': 'Download and run <code>…-win-x64.exe</code>',
    'dlp.win2': 'If <strong>“Windows protected your PC”</strong> appears, click <strong>More info</strong> → <strong>Run anyway</strong>',
    'dlp.win3': 'It installs without admin rights and your fairy appears. You’ll also find it in the Start menu',
    'dlp.winBlocked': 'If a work computer blocks it with no “Run anyway” button, your administrator has locked this down, and it can’t be installed until a signed build is available.',
    'dlp.linuxT': 'Linux (preview)',
